export function filterLayers(opts: {
  stage?: StackStage | "all";
  minTop1?: number;
}): StackLayer[] {
  const { stage = "all", minTop1 = 0 } = opts;
  return STACK_LAYERS.filter((l) => {
    if (stage !== "all" && l.stage !== stage) return false;
    if (l.top1SharePct < minTop1) return false;
    return true;
  });
}

export function fmtPct(n: number, digits = 0): string {
