                  type="number"
                  dataKey="tightness"
                  name="Tightness"
                  domain={[4, 11]}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "Tightness",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <ZAxis type="number" dataKey="leadWeeks" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) =>
                    name === "Top-1 %"
                      ? fmtPct(Number(v))
                      : name === "Tightness"
                        ? String(v)
