"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  FIRM_LEADERBOARD,
  GPU_BOM_CONCENTRATION,
  HEADLINE,
  HHI_BANDS,
  SOURCE_NOTE,
  STACK_LAYERS,
  STAGE_FLOW,
  STAGE_OPTIONS,
  TOP_K_LADDER,
  TIGHTNESS_SCATTER,
  filterLayers,
  fmtHhi,
  fmtPct,
  type StackStage,
} from "@/data/ai-supply-chain-concentration-2026-data";

// viz-types: ranked top1/top3 bars, Lorenz BOM curve, stage median bars, HHI donut, firm leaders, tightness??concentration scatter | layout: default

type ViewId = "ladder" | "lorenz" | "stages" | "hhi" | "firms" | "scatter";
type Metric = "top1" | "top3" | "hhi";

const ROSE = "#f43f5e";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const SLATE = "#64748b";
const TEAL = "#14b8a6";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AiSupplyChainConcentrationDashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [metric, setMetric] = useState<Metric>("top1");
  const [stage, setStage] = useState<StackStage | "all">("all");
  const [minTop1, setMinTop1] = useState<0 | 50 | 70>(0);

  const filtered = useMemo(
    () => filterLayers({ stage, minTop1 }),
    [stage, minTop1],
  );

  const ladderBars = useMemo(() => {
    return [...filtered]
      .map((c) => ({
        ...c,
        value:
          metric === "top1"
            ? c.top1SharePct
            : metric === "top3"
              ? c.top3SharePct
              : c.hhi,
      }))
      .sort((a, b) => b.value - a.value);
  }, [filtered, metric]);

  const metricLabel =
    metric === "top1" ? "Top-1 share %" : metric === "top3" ? "Top-3 share %" : "HHI";

  return (
    <div
      className="space-y-6"
      data-viz="ai-supply-chain-concentration-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-5 text-white shadow-sm sm:px-6">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300/90">
          Semiconductor supply chain ??? concentration lens
        </p>
        <p className="mt-2 max-w-3xl text-sm leading-relaxed text-slate-200 sm:text-base">
          Across{" "}
          <span className="font-semibold text-white">
            {HEADLINE.layersTracked}
          </span>{" "}
          chip-stack layers, median Top-1 share is{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.medianTop1Pct)}
          </span>
          ;{" "}
          <span className="font-semibold text-white">
            {HEADLINE.extremeTop1Count}
          </span>{" "}
          layers clear 70% Top-1. Extreme:{" "}
          {HEADLINE.extremeTop1Label} at{" "}
          <span className="font-semibold text-white">
            {fmtPct(HEADLINE.extremeTop1Pct)}
          </span>
          . Binding mid-stack: CoWoS{" "}
          {fmtPct(HEADLINE.cowosTop1Pct)} ?? HBM{" "}
          {fmtPct(HEADLINE.hbmTop1Pct)} ?? ???5nm foundry{" "}
          {fmtPct(HEADLINE.foundryTop1Pct)}.
        </p>
        <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {TOP_K_LADDER.map((row) => (
            <div
              key={String(row.k)}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-2"
            >
              <p className="text-[11px] uppercase tracking-wide text-slate-400">
                {row.label}
              </p>
              <p className="text-xl font-bold tabular-nums text-white">
                {row.k === 5
                  ? `${row.count}%`
                  : `${row.count}/${HEADLINE.layersTracked}`}
              </p>
              <p className="text-xs text-slate-400">
                {row.k === 5
                  ? "across tracked layers"
                  : `${row.sharePct}% of layers`}
              </p>
            </div>
          ))}
          <div className="rounded-lg border border-white/10 bg-white/5 px-3 py-2">
            <p className="text-[11px] uppercase tracking-wide text-slate-400">
              NVIDIA AI GPU
            </p>
            <p className="text-xl font-bold tabular-nums text-white">
              {fmtPct(HEADLINE.nvidiaGpuSharePct)}
            </p>
            <p className="text-xs text-slate-400">accelerator Top-1</p>
          </div>
        </div>
      </div>

      <div className="flex flex-col gap-3 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "ladder", label: "Ladder" },
            { id: "lorenz", label: "Lorenz" },
            { id: "stages", label: "Stages" },
            { id: "hhi", label: "HHI" },
            { id: "firms", label: "Firms" },
            { id: "scatter", label: "Scatter" },
          ]}
        />
        <ToggleGroup
          label="Metric"
          value={metric}
          onChange={setMetric}
          options={[
            { id: "top1", label: "Top-1" },
            { id: "top3", label: "Top-3" },
            { id: "hhi", label: "HHI" },
          ]}
        />
        <ToggleGroup
          label="Stage"
          value={stage}
          onChange={setStage}
          options={STAGE_OPTIONS.map((o) => ({
            id: o.id,
            label: o.id === "all" ? "All" : o.label,
          }))}
        />
        <ToggleGroup
          label="Min Top-1"
          value={String(minTop1) as "0" | "50" | "70"}
          onChange={(v) => setMinTop1(Number(v) as 0 | 50 | 70)}
          options={[
            { id: "0", label: "Any" },
            { id: "50", label: "???50%" },
            { id: "70", label: "???70%" },
          ]}
        />
      </div>

      {view === "ladder" && (
        <ChartCard
          title="Ranked market shares"
          subtitle={`${metricLabel} by chip-stack layer ??? filter with Stage / Min Top-1`}
        >
          <div className="h-[420px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={ladderBars}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 11, fill: SLATE }}
                  domain={metric === "hhi" ? [0, "auto"] : [0, 100]}
                />
                <YAxis
                  type="category"
                  dataKey="shortLabel"
                  width={96}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip
                  formatter={(v) =>
                    metric === "hhi"
                      ? fmtHhi(Number(v))
                      : fmtPct(Number(v), 0)
                  }
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {ladderBars.map((d) => (
                    <Cell key={d.id} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {view === "lorenz" && (
        <ChartCard
          title="Cumulative share vs equal split"
          subtitle="AI GPU BOM cost mass ??? how fast value concentrates in the first few layers"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={[...GPU_BOM_CONCENTRATION]}
                margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="rank"
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "BOM layer rank",
                    position: "insideBottom",
                    offset: -2,
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <YAxis
                  tick={{ fontSize: 11, fill: SLATE }}
                  domain={[0, 100]}
                  unit="%"
                />
                <Tooltip />
                <Area
                  type="monotone"
                  dataKey="cumulativePct"
                  fill={ROSE}
                  fillOpacity={0.15}
                  stroke={ROSE}
                  strokeWidth={2}
                  name="Cumulative BOM share"
                />
                <Line
                  type="monotone"
                  dataKey="equalPct"
                  stroke={SLATE}
                  strokeDasharray="4 4"
                  strokeWidth={1.5}
                  dot={false}
                  name="Equal split"
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            GPU die + HBM alone already hold ~68% of illustrative AI accelerator
            BOM cost mass ??? concentration upstream of assembly.
          </p>
        </ChartCard>
      )}

      {view === "stages" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Stage median Top-1 / Top-3"
            subtitle="Materials ??? equipment ??? fab ??? memory ??? packaging ??? design ??? accelerator"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart
                  data={STAGE_FLOW}
                  margin={{ top: 8, right: 16, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10, fill: SLATE }} />
                  <YAxis
                    tick={{ fontSize: 11, fill: SLATE }}
                    domain={[0, 100]}
                    unit="%"
                  />
                  <Tooltip />
                  <Bar
                    dataKey="medianTop1"
                    fill={SKY}
                    name="Median Top-1"
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="medianTop3"
                    fill={ROSE}
                    name="Median Top-3"
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    type="monotone"
                    dataKey="medianTop1"
                    stroke={AMBER}
                    strokeWidth={2}
                    dot={{ r: 3 }}
                    name="Top-1 path"
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-3 space-y-1 text-xs text-slate-600">
              {STAGE_FLOW.map((s) => (
                <li key={s.stage}>
                  <span className="font-semibold text-slate-800">{s.label}</span>
                  : binding {s.bindingLayer} (Top-1 {fmtPct(s.medianTop1)})
                </li>
              ))}
            </ul>
          </ChartCard>
          <ChartCard
            title="Layer tightness heatmap proxy"
            subtitle="Editorial bottleneck score (1???10) ordered by stage flow"
          >
            <div className="h-[340px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...STACK_LAYERS].sort(
                    (a, b) => b.tightness - a.tightness,
                  )}
                  layout="vertical"
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    domain={[0, 10]}
                    tick={{ fontSize: 11, fill: SLATE }}
                  />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={96}
                    tick={{ fontSize: 11, fill: SLATE }}
                  />
                  <Tooltip />
                  <Bar dataKey="tightness" radius={[0, 4, 4, 0]}>
                    {[...STACK_LAYERS]
                      .sort((a, b) => b.tightness - a.tightness)
                      .map((d) => (
                        <Cell key={d.id} fill={d.fill} />
                      ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "hhi" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="HHI band mix"
            subtitle="How many layers sit in extreme / high / moderate concentration bands"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={[...HHI_BANDS]}
                    dataKey="count"
                    nameKey="label"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={100}
                    paddingAngle={2}
                  >
                    {HHI_BANDS.map((b) => (
                      <Cell key={b.id} fill={b.fill} />
                    ))}
                  </Pie>
                  <Tooltip />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="mt-2 space-y-1 text-xs text-slate-600">
              {HHI_BANDS.map((b) => (
                <li key={b.id}>
                  <span
                    className="mr-2 inline-block h-2 w-2 rounded-full"
                    style={{ background: b.fill }}
                  />
                  {b.label}: {b.count} layers
                </li>
              ))}
            </ul>
          </ChartCard>
          <ChartCard
            title="HHI by layer"
            subtitle="Derived Herfindahl index from rounded firm shares (illustrative)"
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...filtered].sort((a, b) => b.hhi - a.hhi)}
                  layout="vertical"
                  margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis type="number" tick={{ fontSize: 11, fill: SLATE }} />
                  <YAxis
                    type="category"
                    dataKey="shortLabel"
                    width={96}
                    tick={{ fontSize: 11, fill: SLATE }}
                  />
                  <Tooltip formatter={(v) => fmtHhi(Number(v))} />
                  <Bar dataKey="hhi" radius={[0, 4, 4, 0]}>
                    {[...filtered]
                      .sort((a, b) => b.hhi - a.hhi)
                      .map((d) => (
                        <Cell key={d.id} fill={d.fill} />
                      ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "firms" && (
        <ChartCard
          title="Who leads how many layers"
          subtitle="Recurring Top-1 names across the 12-layer chip-stack ledger"
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={[...FIRM_LEADERBOARD]}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  allowDecimals={false}
                  domain={[0, 3]}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <YAxis
                  type="category"
                  dataKey="firm"
                  width={88}
                  tick={{ fontSize: 11, fill: SLATE }}
                />
                <Tooltip />
                <Bar dataKey="top1Count" name="Top-1 layer count" radius={[0, 4, 4, 0]}>
                  {FIRM_LEADERBOARD.map((d) => (
                    <Cell key={d.firm} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            TSMC alone leads two binding layers (???5nm foundry and CoWoS). Most
            other names are single-layer monopolists or oligopoly leaders.
          </p>
        </ChartCard>
      )}

      {view === "scatter" && (
        <ChartCard
          title="Tightness ?? Top-1 concentration"
          subtitle="Bubble size = lead weeks; upper-right = scarce and concentrated"
        >
          <div className="h-[400px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 16, left: 0, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="top1"
                  name="Top-1 %"
                  domain={[20, 105]}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "Top-1 share %",
                    position: "insideBottom",
                    offset: -2,
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="tightness"
                  name="Tightness"
                  domain={[4, 11]}
                  tick={{ fontSize: 11, fill: SLATE }}
                  label={{
                    value: "Tightness",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11, fill: SLATE },
                  }}
                />
                <ZAxis type="number" dataKey="leadWeeks" range={[60, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(v, name) =>
                    name === "Top-1 %"
                      ? fmtPct(Number(v))
                      : name === "Tightness"
                        ? String(v)
                        : v
                  }
                />
                <Scatter data={TIGHTNESS_SCATTER} name="Layers">
                  {TIGHTNESS_SCATTER.map((d) => (
                    <Cell key={d.id} fill={d.fill} />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            CoWoS sits max-tightness with high Top-1; EUV and ???5nm foundry sit in
            the same upper-right quadrant. Broader WFE is less concentrated and
            less binding.
          </p>
        </ChartCard>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="sr-only">
        Chart types: ranked bars, Lorenz area+line, stage composed bars, HHI
        donut, firm bars, tightness scatter. Controls: view, metric, stage, min
        Top-1. Layers tracked: {STACK_LAYERS.length}. Accent {TEAL}.
      </p>
    </div>
  );
}

