const dashboardSrc = fs.readFileSync(dashPath, "utf8");
assert.ok(
  dashboardSrc.includes('data-viz="ai-supply-chain-concentration-2026"'),
  "Dashboard wired",
);

const markers = [
  "Semiconductor supply chain ??? concentration lens",
  "Ranked market shares",
  "Cumulative share vs equal split",
];

async function clickBtn(page, name) {
  console.log(`??? click ${name}`);
  await page.locator("button", { hasText: name }).first().click({ timeout: 8000 });
  await page.waitForTimeout(150);
}

async function main() {
  const outDir = path.join(root, "out");
  if (!fs.existsSync(outDir)) {
    console.error("??? Missing out/ ??? run npm run build first");
    process.exit(1);
  }
  const port = Number(process.env.SMOKE_PORT || 4188);
  const server = await startStaticServer(outDir, port);
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.setDefaultTimeout(15000);
  try {
    const candidates = [
      `http://127.0.0.1:${port}/blog/${slug}.html`,
      `http://127.0.0.1:${port}/blog/${slug}/`,
      `http://127.0.0.1:${port}/blog/${slug}`,
    ];
    let loaded = false;
    for (const url of candidates) {
      const res = await page.goto(url, {
        waitUntil: "domcontentloaded",
        timeout: 45000,
      });
      if (res && res.ok()) {
        loaded = true;
        break;
      }
    }
    if (!loaded) {
      console.error("??? Failed to load post HTML");
      process.exit(1);
    }
    await page.waitForSelector(
      '[data-viz="ai-supply-chain-concentration-2026"]',
      { timeout: 20000 },
    );
    for (const m of markers) {
      if (m === "Cumulative share vs equal split") {
        await clickBtn(page, "Lorenz");
      }
      await page.getByText(m, { exact: false }).first().waitFor({ timeout: 20000 });
      console.log(`??? ${m}`);
    }
    await clickBtn(page, "Top-3");
    await clickBtn(page, "HHI");
    await clickBtn(page, "Stages");
    await page
      .getByText("Stage median Top-1 / Top-3", { exact: false })
      .first()
      .waitFor({ timeout: 10000 });
    console.log("??? Stage median Top-1 / Top-3");
    await clickBtn(page, "Firms");
    await clickBtn(page, "Scatter");
    await clickBtn(page, "???70%");
    await clickBtn(page, "Packaging");
    await clickBtn(page, "Ladder");
    await clickBtn(page, "Top-1");
    await clickBtn(page, "All");
    await clickBtn(page, "Any");
    console.log("??? auditVizInteractions");
    const audit = await auditVizInteractions(page);
    if (audit.issues?.length) {
      console.error("??? Viz interaction audit failed", audit);
      process.exit(1);
    }
    if (audit.warnings?.length) {
      console.log("??? warnings:", audit.warnings.join("; "));
    }
    await page
      .locator('img[src*="industry-ai-supply-chain-concentration-2026-hero"]')
      .first()
      .waitFor({ timeout: 10000 });
    console.log("??? hero image");
    console.log("??? QA passed:", slug);
  } finally {
    await browser.close();
    await stopStaticServer(server);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

